<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { ApiError, describeError, formatDate, request, workspacePath, type Workspace } from './api'
import { readScenarioContext, scenarioContextHref } from './scenario-context'
import type { WorkbenchItem, ClassificationWorkbenchPage } from './classification-workbench'
import { parseBrowserAnnotation, type BrowserAnnotation, type BrowserAnnotationInput, type BrowserAnnotationCandidate } from './browser-annotations'
const props=defineProps<{workspace:Workspace}>();const emit=defineEmits<{sessionExpired:[]}>()
const base=workspacePath(props.workspace.slug),canEdit=computed(()=>['owner','operator'].includes(props.workspace.role))
const assetId=ref(readScenarioContext(props.workspace.slug).assetId||''),query=ref(''),assets=ref<WorkbenchItem[]>([]),items=ref<BrowserAnnotation[]>([]),next=ref<number|null>(null),selected=ref<BrowserAnnotation|null>(null)
const candidates=ref<BrowserAnnotationCandidate[]>([])
const draft=ref<Omit<BrowserAnnotationInput,'assetId'>|null>(null),accepted=ref(false),busy=ref(false),loading=ref(false),error=ref(''),notice=ref('');const controller=new AbortController();let loadSequence=0,findSequence=0
const href=(page:string,asset?:number)=>scenarioContextHref(props.workspace.slug,page,asset?{assetId:String(asset)}:{})
function failed(e:unknown){if(controller.signal.aborted)return;if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=e instanceof Error&&!(e instanceof ApiError)&&!(e instanceof TypeError)?e.message:describeError(e)}
async function findAssets(){const seq=++findSequence;try{const result=await request<ClassificationWorkbenchPage>(base+'/classification/workbench?pageSize=50&q='+encodeURIComponent(query.value),{signal:controller.signal});if(seq!==findSequence)return;assets.value=result.items;if(assetId.value&&!assets.value.some(a=>String(a.asset.id)===assetId.value)){const result=await request<WorkbenchItem>(base+'/classification/assets/'+encodeURIComponent(assetId.value),{signal:controller.signal});if(seq===findSequence)assets.value.unshift(result)}}catch(e){failed(e)}}
async function load(append=false){const seq=++loadSequence;loading.value=true;error.value='';try{const q=new URLSearchParams();if(assetId.value)q.set('assetId',assetId.value);if(append&&next.value)q.set('before',String(next.value));const result=await request<{items:BrowserAnnotation[];nextCursor:number|null}>(base+'/browser-annotations?'+q,{signal:controller.signal});if(seq!==loadSequence)return;items.value=append?[...items.value,...result.items]:result.items;next.value=result.nextCursor;selected.value=null}catch(e){failed(e)}finally{if(seq===loadSequence)loading.value=false}}
function receive(value:unknown){candidates.value=[];draft.value=parseBrowserAnnotation(value);accepted.value=false;notice.value='标签已载入预览，尚未保存。请核对来源、关联资产及每项字段。'}
async function fileChanged(event:Event){error.value='';const input=event.target as HTMLInputElement;try{const file=input.files?.[0];if(!file)return;if(file.size>96*1024)throw new Error('标签文件不得超过96KiB。');receive(JSON.parse(await file.text()))}catch(e){failed(e)}finally{input.value=''}}
async function match(){if(!draft.value||!assetId.value||!canEdit.value||busy.value)return;busy.value=true;error.value='';candidates.value=[];try{const r=await request<{candidates:BrowserAnnotationCandidate[]}>(base+'/browser-annotations/match',{method:'POST',body:JSON.stringify({assetId:Number(assetId.value),...draft.value}),signal:controller.signal});candidates.value=r.candidates;notice.value=r.candidates.length?'已形成真实OpenAPI字段同名候选。请逐项选择是否关联；这不证明已观察到页面与接口血缘。':'未找到同名契约字段。范围仅为所选资产已导入OpenAPI中已识别字段，无匹配保持未知。'}catch(e){failed(e)}finally{busy.value=false}}
function assetChanged(){candidates.value=[];if(draft.value)for(const field of draft.value.fields)delete field.apiCandidate;void load()}
async function save(){if(!draft.value||!canEdit.value||!accepted.value||!assetId.value||busy.value)return;busy.value=true;error.value='';try{const item=await request<BrowserAnnotation>(base+'/browser-annotations',{method:'POST',body:JSON.stringify({assetId:Number(assetId.value),...draft.value}),signal:controller.signal});draft.value=null;accepted.value=false;await load();selected.value=item;notice.value=item.replayed?'相同标注已保存，已返回原始记录。':'人工字段标注已保存。正式分类结果保持独立认定。'}catch(e){failed(e)}finally{busy.value=false}}
onMounted(async()=>{const url=new URL(location.href),[path,qs='']=url.hash.split('?'),params=new URLSearchParams(qs);const encoded=params.get('annotation');if(encoded){params.delete('annotation');url.hash=path+(params.size?'?'+params:'');history.replaceState(history.state,'',url);try{if(encoded.length>132000)throw new Error('导入片段过大。');const binary=atob(encoded.replace(/-/g,'+').replace(/_/g,'/'));receive(JSON.parse(new TextDecoder().decode(Uint8Array.from(binary,c=>c.charCodeAt(0)))))}catch(e){failed(e)}}await Promise.all([findAssets(),load()])})
onBeforeUnmount(()=>{controller.abort();draft.value=null})
</script>
<template>
<div class="annotation-panel">
  <div class="panel-heading"><div><h2>业务页面字段标注</h2><p>用户主动授权当前页，采集可见字段标识，再明确关联实际资产。每次保存形成独立人工标注快照。</p></div><a class="button" href="/extensions/browser-field-labeler.zip" download>下载扩展源码 ZIP</a></div>
  <p v-if="error" class="message message-error" role="alert">{{error}}</p><p v-if="notice" class="message" role="status">{{notice}}</p>
  <details class="annotation-help"><summary>授权与操作说明</summary><ol><li>解压源码，在Chrome或Edge扩展管理页选择“加载已解压的扩展程序”。仅使用activeTab与scripting，无全站访问权限。</li><li>在已获授权的业务页面打开表单或弹窗，点击扩展确认授权并读取当前可见字段。</li><li>逐项预览，粘贴已登录的平台工作区地址并前往平台。也可导入同格式JSON。</li><li>选择已登记资产（可选API或字段资产），核对人工标识与字段映射，再保存。</li></ol><p>不读取输入值、密码、页面正文或后台流量，不自动翻页，不按DOM推断血缘。跨域iframe、关闭弹窗和未渲染列表未覆盖。字段标签也可能包含业务信息，请在传递前核对。</p></details>
  <form class="annotation-scope" @submit.prevent="findAssets"><label>查找实际资产<input v-model="query" type="search" maxlength="100" placeholder="资产名称或系统"></label><button class="button" type="submit">查询资产</button><label>关联资产<select v-model="assetId" :disabled="busy" @change="assetChanged"><option value="">请选择资产</option><option v-for="a in assets" :key="a.asset.id" :value="String(a.asset.id)">{{a.asset.name}} · {{a.catalog?.kind||a.asset.system}} · #{{a.asset.id}}</option></select></label><label v-if="canEdit" class="button annotation-upload">导入标签 JSON<input type="file" :disabled="busy" accept="application/json,.json" @change="fileChanged"></label></form>
  <section v-if="draft" class="panel annotation-preview"><div class="panel-heading"><div><h3>待保存标签 · {{draft.fields.length}}项</h3><p>页面路径可先清理；所有关联由当前用户明确确认。</p></div><div class="actions"><button class="button" :disabled="!assetId||busy||!canEdit" @click="match">匹配所选资产OpenAPI字段</button><button class="button" :disabled="busy" @click="draft=null;candidates=[]">取消导入</button></div></div>
    <form @submit.prevent="save"><div class="annotation-scope"><label>来源域名<input v-model="draft.page.origin" :disabled="busy" type="url" maxlength="240" required></label><label>页面路径（不含参数）<input v-model="draft.page.path" :disabled="busy" maxlength="400" required></label><label>页面说明<input v-model="draft.page.title" :disabled="busy" maxlength="120"></label></div>
    <div class="table-wrap"><table><thead><tr><th scope="col">字段标识</th><th scope="col">人工数据标识</th><th scope="col">人工声明字段映射</th><th scope="col">备注</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="(field,index) in draft.fields" :key="index"><th scope="row">{{field.label||field.name}}<small>{{field.name}} · {{field.elementKind}}</small></th><td><input v-model="field.category" :disabled="busy" maxlength="80" :aria-label="`${field.label||field.name}的数据标识`" placeholder="如：经营收入"></td><td><input v-model="field.targetField" :disabled="busy" maxlength="160" :aria-label="`${field.label||field.name}的字段映射`" placeholder="可选，人工关联"><select v-if="candidates.some(c=>c.index===index)" v-model="field.apiCandidate" :disabled="busy" :aria-label="`${field.label||field.name}的同名契约候选`"><option :value="undefined">不采用接口候选</option><option v-for="c in candidates.filter(c=>c.index===index)" :key="c.scanId+':'+c.field+':'+c.location" :value="c">同名候选：{{c.method}} {{c.route}} · {{c.location}} / {{c.field}}</option></select><small v-if="field.apiCandidate">已人工选择契约候选 · 扫描 #{{field.apiCandidate.scanId}}；未验证血缘</small></td><td><input v-model="field.note" :disabled="busy" maxlength="240" :aria-label="`${field.label||field.name}的备注`"></td><td><button type="button" class="button" :disabled="busy" @click="draft.fields.splice(index,1);candidates=[]">移除</button></td></tr></tbody></table></div>
    <footer class="annotation-footer"><label><input v-model="accepted" type="checkbox">已核对授权、页面标识及人工关联；不含输入值或秘密</label><button class="button button-primary" :disabled="busy||!canEdit||!assetId||!accepted||!draft.fields.length">{{busy?'保存中…':'保存人工标注'}}</button></footer></form>
  </section>
  <section class="panel"><div class="panel-heading"><div><h3>已保存标注</h3><p>{{assetId?'所选资产':'工作区'}}的人工标注记录；与源端自动观察和正式分类分开保留。</p></div><button class="button" :disabled="loading" @click="load()">刷新</button></div><p v-if="loading" class="message" role="status">正在读取标注…</p><p v-else-if="!items.length" class="message">当前范围还没有人工字段标注。</p><div v-else class="table-wrap"><table><thead><tr><th>关联资产</th><th>页面标识</th><th>字段</th><th>记录人 / 时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><th scope="row"><a :href="href('classification/'+item.assetId,item.assetId)">{{item.assetName}}</a></th><td>{{item.page.title||item.page.origin}}<small>{{item.page.path}}</small></td><td>{{item.fields.length}}项</td><td>{{item.actor}}<small>{{formatDate(item.createdAt)}}</small></td><td><button class="button" @click="selected=item">查看快照</button></td></tr></tbody></table></div><div v-if="next" class="annotation-footer"><button class="button" :disabled="loading" @click="load(true)">加载更早标注</button></div></section>
  <section v-if="selected" class="panel"><div class="panel-heading"><div><h3>标注快照 #{{selected.id}}</h3><p>{{selected.page.origin}}{{selected.page.path}} · {{selected.actor}} · {{formatDate(selected.createdAt)}}</p></div><a class="button" :href="base+'/browser-annotations/'+selected.id" download="browser-annotations.json">导出 JSON</a></div><div class="table-wrap"><table><thead><tr><th>页面字段</th><th>人工数据标识</th><th>人工字段映射</th><th>备注</th></tr></thead><tbody><tr v-for="(field,i) in selected.fields" :key="i"><th scope="row">{{field.label||field.name}}<small>{{field.name}} · {{field.locator}}</small></th><td>{{field.category||'未标注'}}</td><td>{{field.targetField||'仅关联资产'}}<small v-if="field.apiCandidate">人工采用同名候选：{{field.apiCandidate.method}} {{field.apiCandidate.route}} · {{field.apiCandidate.location}} / {{field.apiCandidate.field}} · 扫描 #{{field.apiCandidate.scanId}}；未验证血缘</small></td><td>{{field.note||'—'}}</td></tr></tbody></table></div><p class="annotation-digest">快照摘要 {{selected.snapshotDigest}}</p></section>
</div>
</template>
<style scoped>
.annotation-panel{display:grid;gap:18px;min-width:0}.annotation-panel>.panel-heading{padding:0}.annotation-panel h2{font-size:18px}.annotation-panel h3{font-size:15px}.annotation-panel p{font-size:12px;line-height:1.8;color:var(--secondary)}.annotation-scope{display:flex;flex-wrap:wrap;gap:12px;align-items:end;padding:16px 18px}.annotation-panel>.annotation-scope{padding:0}.annotation-scope label{display:grid;gap:7px;font-size:12px;flex:1;min-width:180px}.annotation-panel input:not([type=checkbox]),.annotation-panel select{font:inherit;color:var(--ink);background:var(--surface);border:1px solid var(--input-line);border-radius:6px;padding:9px 10px;min-width:0;max-width:100%}.annotation-upload{cursor:pointer;flex:none!important;min-width:0!important}.annotation-upload input{width:0;height:0;position:absolute;opacity:0}.annotation-upload:focus-within{outline:2px solid var(--accent);outline-offset:3px}.annotation-help{padding:14px 18px;background:var(--surface-subtle);border:1px solid var(--line);border-radius:8px;font-size:12px;line-height:1.9}.annotation-help summary{cursor:pointer;font-weight:700;color:var(--ink)}.annotation-help ol{padding-left:20px}.annotation-panel table{border-collapse:collapse;width:100%;min-width:760px}.annotation-panel th,.annotation-panel td{text-align:left;padding:12px 14px;font-size:12px;border-bottom:1px solid var(--line);vertical-align:top}.annotation-panel th{font-weight:600}.annotation-panel th small,.annotation-panel td small{display:block;color:var(--secondary);font-size:11px;font-weight:400;margin-top:4px;overflow-wrap:anywhere}.annotation-panel td input{width:100%;min-width:120px}.annotation-footer{display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:14px;padding:15px 18px}.annotation-footer label{font-size:12px;display:flex;align-items:center;gap:8px;margin-right:auto}.annotation-digest{padding:0 18px 14px;overflow-wrap:anywhere}.annotation-panel a{color:var(--accent)}
</style>
